 3→/** 5400 gives "1h30m", 45 gives "45s", 0 gives "0s". */
 4→export function formatDuration(seconds) {
 5→  const h = Math.floor(seconds / 3600);
 6→  const m = Math.floor((seconds % 3600) / 60);
 7→  const s = seconds % 60;
 8→  const parts = [h && `${h}h`, m && `${m}m`, s && `${s}s`].filter(Boolean);
 9→  return parts.length ? parts.join("") : "0s";
10→}
